-- 125: Original BrillaPrep WASSCE BrillaPrep IRS beta content blueprint beta questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_125_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_125_guard;
INSERT INTO _migration_125_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_016' AND NOT (q.topic_id IS 'topic_was_irs_4' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does tawhid mean in Islamic belief?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Worship of several independent deities","B. Rejection of all prophets","C. A method of commercial accounting","D. Belief in the absolute oneness of Allah"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Tawhid is the foundation of Islamic belief: Allah alone is the creator and deserves worship without partners or rivals. Therefore the correct answer is D: Belief in the absolute oneness of Allah.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_016' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_125_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_017' AND NOT (q.topic_id IS 'topic_was_irs_4' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which is one of the Five Pillars of Islam?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Zakah","B. Tribal superiority","C. Monastic isolation","D. Fortune telling"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Zakah is obligatory almsgiving on qualifying wealth and links worship with purification of wealth and responsibility toward eligible recipients. Therefore the correct answer is A: Zakah.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_017' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_125_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_018' AND NOT (q.topic_id IS 'topic_was_irs_4' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the primary declaration contained in the Shahadah?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Every nation must use one language","B. There is no deity worthy of worship except Allah and Muhammad is His messenger","C. Wealth determines spiritual rank","D. Only scholars are accountable for conduct"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The testimony expresses monotheism and acceptance of Muhammad’s prophethood, forming the verbal foundation of Muslim commitment. Therefore the correct answer is B: There is no deity worthy of worship except Allah and Muhammad is His messenger.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_018' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_125_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_019' AND NOT (q.topic_id IS 'topic_was_irs_4' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does belief in qadar affirm?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Human beings have no moral accountability","B. Planning for the future is forbidden","C. Allah’s knowledge and decree while humans remain responsible for chosen actions","D. Natural causes never operate"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Belief in divine decree encourages trust in Allah without cancelling effort, choice, planning or accountability for deliberate conduct. Therefore the correct answer is C: Allah’s knowledge and decree while humans remain responsible for chosen actions.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_019' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_125_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_020' AND NOT (q.topic_id IS 'topic_was_irs_4' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Who are the messengers in Islamic belief?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Angels who became human permanently","B. Rulers selected only by wealth","C. Authors of every historical book","D. Human beings chosen by Allah to convey guidance"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Muslims believe Allah selected messengers from humanity, gave them revelation and made them models of faithful conduct. Therefore the correct answer is D: Human beings chosen by Allah to convey guidance.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_020' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
